begin;

-- idea-to-pr: generated by `npm run guide:content` from content/guide/idea-to-pr.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 15,
  "outcome": "Вы проводите одну настоящую задачу своего проекта от идеи до слитого PR, используя весь маршрут, и знаете, где вмешивались сами.",
  "blocks": [
    {
      "type": "text",
      "text": "Пройденные этапы — это части одного процесса. Здесь вы собираете их в одну цепочку на реальной задаче: не учебной, а той, что всё равно стоит в вашем списке. Проверки в конце нет: результат — ваш PR."
    },
    {
      "type": "heading",
      "text": "Маршрут одной задачи"
    },
    {
      "type": "list",
      "items": [
        "**Задача с критерием**: что должно работать и как это проверить (шаг 3.1).",
        "**Исследование** в субагенте: где это в коде, что уже есть (шаг 6.1).",
        "**План** в режиме планирования, а правки — только после согласования (шаг 3.2).",
        "**Шаги**, каждый с проверкой: тест, сборка, ручной сценарий (шаги 3.3 и 3.4).",
        "**Ревью**: diff, тесты как контракт, безопасность (шаги 4.1–4.4), лучше — ревьюер в чистом контексте (шаг 6.3).",
        "**Коммиты и PR** по правилам проекта, CI проверяет за вас (шаги 5.4 и 5.5)."
      ]
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция всей задачи: разработчик ставит задачу «экспорт заказов в CSV» с критерием, агент исследует код субагентом, предлагает план, выполняет его по шагам с тестами, ревьюер в чистом контексте находит пропущенное экранирование, после исправления агент делает коммит и открывает PR, CI проходит.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Экспорт заказов в CSV. Готово, если файл открывается в Excel и тест экспорта зелёный. Сначала план.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Explore: заказы — src/orders, похожий экспорт — src/reports/csv.ts"
        },
        {
          "kind": "meta",
          "text": "План: 3 шага, правок нет до согласования"
        },
        {
          "kind": "edit",
          "text": "src/orders/export.ts",
          "diff": "+64"
        },
        {
          "kind": "pass",
          "text": "npm test -- orders — пройдено"
        },
        {
          "kind": "info",
          "text": "reviewer: запятые и кавычки в названиях товаров не экранируются"
        },
        {
          "kind": "edit",
          "text": "src/orders/export.ts",
          "diff": "+9 −2"
        },
        {
          "kind": "command",
          "text": "gh pr create --title \"feat: export orders to CSV\"",
          "typed": true
        },
        {
          "kind": "done",
          "text": "PR открыт, CI зелёный. Осталось ваше ревью и слияние."
        }
      ]
    },
    {
      "type": "code",
      "file": "docs/capstone.md",
      "code": "# Выпускная задача\n\nЗадача:\nКритерий готовности:\n\n## Ход работы\n- [ ] исследование (субагент)\n- [ ] план согласован\n- [ ] шаги с проверками\n- [ ] ревью в чистом контексте\n- [ ] PR и зелёный CI\n\n## Где я вмешался\n- \n\n## Что агент сделал без меня\n- ",
      "caption": "Ведите заметки по ходу: раздел «Где я вмешался» понадобится в следующем шаге."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Не берите «переписать всё»",
      "text": "Выпускная задача должна быть настоящей, но обозримой: на день-два работы, с понятным критерием. Огромная задача проверяет терпение, а не процесс."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Сливаете вы, а не агент",
      "text": "Последнее решение остаётся за вами: прочитайте итоговый diff целиком, как чужой PR, и только потом сливайте (шаг 4.1)."
    }
  ],
  "practice": {
    "task": "Выберите реальную задачу своего проекта и проведите её по всему маршруту: критерий, исследование, план, шаги с проверками, ревью в чистом контексте, PR. Ведите заметки по шаблону выше.",
    "done": [
      "PR слит или готов к слиянию, CI зелёный;",
      "у задачи был критерий, и он выполнен;",
      "вы записали, где вмешивались сами и почему."
    ]
  }
}$json$::jsonb where step_id = 'idea-to-pr';
delete from private.guide_checks where step_id = 'idea-to-pr';

-- before-after: generated by `npm run guide:content` from content/guide/before-after.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы сравниваете, как работали раньше и как работаете с агентом, на цифрах и фактах, а не на ощущениях.",
  "blocks": [
    {
      "type": "text",
      "text": "Ощущение «стало быстрее» обманчиво: время на ревью и переделки легко не заметить. Честное сравнение показывает, что действительно изменилось, и где агент пока не помогает."
    },
    {
      "type": "heading",
      "text": "Что измерять"
    },
    {
      "type": "list",
      "items": [
        "**Время** от задачи до PR, включая ревью и исправления.",
        "**Ручная работа**: сколько правок вы внесли сами и почему.",
        "**Ошибки до слияния**: что поймали тесты, хуки и ревьюер, а что — только вы.",
        "**Граница делегирования**: какие задачи вы теперь отдаёте целиком, а какие оставили себе (шаг 4.5)."
      ]
    },
    {
      "type": "compare",
      "before": {
        "label": "Было",
        "text": "Экспорт отчёта в CSV: два дня. Сам искал похожий код, сам писал тесты, баг с кавычками нашли пользователи.",
        "note": "Время уходило на поиск и рутину, а проверка держалась на внимательности."
      },
      "after": {
        "label": "Стало",
        "text": "Экспорт заказов в CSV: полдня. Агент нашёл образец и написал код по плану, ревьюер поймал кавычки до PR, CI проверил сборку.",
        "note": "Моя работа — критерий, план, ревью и решение о слиянии."
      }
    },
    {
      "type": "code",
      "file": "docs/before-after.md",
      "code": "# Было / Стало\n\n| | Было | Стало |\n|---|---|---|\n| Задача | | |\n| Время до PR | | |\n| Правок руками | | |\n| Ошибки до слияния | | |\n\n## Что отдаю агенту целиком\n- \n\n## Что оставляю себе и почему\n- ",
      "caption": "Сравнивайте похожие задачи. Колонку «Стало» заполните по заметкам из шага ★.1."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Сравнивайте похожее",
      "text": "Не ставьте лучшую новую задачу рядом с худшей старой. Берите задачи одного размера и типа — иначе сравнение покажет удачу, а не процесс."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "«Не стало лучше» — тоже результат",
      "text": "Если где-то агент не ускорил работу, это ценная находка: там проходит ваша граница делегирования. Запишите её, чтобы не тратить время повторно."
    }
  ],
  "practice": {
    "task": "Заполните «Было / Стало» по шаблону: возьмите задачу из шага ★.1 и похожую задачу, сделанную раньше без агента. Отдельно запишите, что вы теперь отдаёте агенту целиком, а что оставляете себе.",
    "done": [
      "обе колонки заполнены фактами, а не впечатлениями;",
      "сравниваются задачи похожего размера;",
      "записано хотя бы одно место, где агент пока не помогает."
    ]
  }
}$json$::jsonb where step_id = 'before-after';
delete from private.guide_checks where step_id = 'before-after';

-- public-profile: generated by `npm run guide:content` from content/guide/public-profile.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы показываете результат маршрута публично: PR, сравнение «Было / Стало» и настройки проекта, которые доказывают, что это система, а не разовая удача.",
  "blocks": [
    {
      "type": "text",
      "text": "Слова «умею работать с агентами» ничего не доказывают. Доказывает то, что можно открыть и проверить: настоящий PR, правила проекта, честное сравнение. Этот шаг собирает их в одно место."
    },
    {
      "type": "heading",
      "text": "Что показать"
    },
    {
      "type": "list",
      "items": [
        "**PR из шага ★.1** с описанием: задача, критерий, как шла работа, где вы вмешались.",
        "**«Было / Стало»** из шага ★.2 — с цифрами и с тем, что вы оставили себе.",
        "**Система проекта**: CLAUDE.md, правила разрешений, хуки, свои команды и субагенты (этапы 2, 5 и 6)."
      ]
    },
    {
      "type": "code",
      "file": "README.md",
      "code": "## Как я работаю с агентами\n\n- Задача с критерием → план → шаги с проверками → ревью → PR\n- Пример: [экспорт заказов в CSV](ссылка на PR)\n- Было / Стало: [сравнение](docs/before-after.md)\n- Правила проекта: [CLAUDE.md](CLAUDE.md), хуки и субагенты в `.claude/`",
      "caption": "Раздел для README проекта или вашего профиля на GitHub. Ссылки ведут на то, что можно проверить."
    },
    {
      "type": "compare",
      "before": {
        "label": "Пусто",
        "text": "Активно использую ИИ-инструменты в разработке.",
        "note": "Так может написать кто угодно: проверить нечего."
      },
      "after": {
        "label": "Проверяемо",
        "text": "Веду задачи с агентом от критерия до PR: пример PR, правила проекта и сравнение «Было / Стало» — по ссылкам.",
        "note": "Каждое утверждение открывается одной ссылкой."
      }
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Перед публикацией — ревью на секреты",
      "text": "Проверьте всё, что выкладываете: ключи, внутренние адреса, данные клиентов, чужой код по договору. Рабочий проект показывайте только с разрешения; если нельзя — повторите приём на своём (шаг 4.4)."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Рассказывайте о процессе, а не о модели",
      "text": "Модели и инструменты сменятся. Навык ставить критерии, ревьюить и автоматизировать проверки останется — его и показывайте."
    },
    {
      "type": "text",
      "text": "На этом маршрут пройден. Дальше — та же цепочка на каждой задаче: с каждым разом она занимает меньше внимания и даёт больше результата."
    }
  ],
  "practice": {
    "task": "Соберите публичный раздел о своей работе с агентами в README проекта или профиля: ссылка на PR из шага ★.1, сравнение из ★.2 и ссылки на правила проекта. Перед публикацией проверьте всё на секреты и закрытые данные.",
    "done": [
      "раздел опубликован и каждое утверждение подкреплено ссылкой;",
      "в публичных материалах нет ключей, внутренних адресов и чужих данных;",
      "по разделу понятно, как вы работаете, даже без вашего рассказа."
    ]
  }
}$json$::jsonb where step_id = 'public-profile';
delete from private.guide_checks where step_id = 'public-profile';

commit;
